         {ld_mid2, function(x,y) local t = smoothstep(482, 530, y) return t * (1 - smoothstep(575, 660, y)) end},
         {ld_near2, function(x,y) return smoothstep(575, 660, y) + 0.4*smoothstep(150, 0, x)*smoothstep(520, 640, y) end}}
end
